package com.byawasaya.platform.auth;

import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.security.SecureRandom; import java.time.Duration; import java.time.Instant; import java.util.Base64; import java.util.HexFormat;
import org.springframework.beans.factory.ObjectProvider; import org.springframework.beans.factory.annotation.Value; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import com.byawasaya.platform.audit.AuditService;

@Service
public class EmailActionService {
 private final EmailActionTokenRepository tokens; private final UserAccountRepository accounts; private final ObjectProvider<JavaMailSender> mailProvider; private final AuditService audit; private final String from; private final String frontendUrl; private final SecureRandom random=new SecureRandom();
 public EmailActionService(EmailActionTokenRepository tokens,UserAccountRepository accounts,ObjectProvider<JavaMailSender> mailProvider,AuditService audit,@Value("${app.mail.from:no-reply@byawasaya.local}")String from,@Value("${app.frontend-url:http://localhost:5173}")String frontendUrl){this.tokens=tokens;this.accounts=accounts;this.mailProvider=mailProvider;this.audit=audit;this.from=from;this.frontendUrl=frontendUrl;}
 @Transactional public void sendVerification(UserAccount account){issueToken(account,"VERIFY_EMAIL",Duration.ofHours(24),"Verify your Byawasaya email","/verify-email?token=");}
 @Transactional public void sendPasswordReset(UserAccount account){issueToken(account,"RESET_PASSWORD",Duration.ofMinutes(30),"Reset your Byawasaya password","/reset-password?token=");}
 @Transactional public void sendAccountSetup(UserAccount account){issueToken(account,"SET_PASSWORD",Duration.ofHours(48),"Set up your Byawasaya staff account","/reset-password?token=");}
 private void issueToken(UserAccount account,String type,Duration lifetime,String subject,String path){for(EmailActionToken previous:tokens.findAllByAccountIdAndActionTypeAndConsumedAtIsNull(account.getId(),type))previous.consume();byte[] bytes=new byte[32];random.nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);tokens.save(new EmailActionToken(account.getId(),hash(raw),type,Instant.now().plus(lifetime)));JavaMailSender mail=mailProvider.getIfAvailable();if(mail==null)throw new IllegalStateException("Email delivery is not configured.");SimpleMailMessage message=new SimpleMailMessage();message.setFrom(from);message.setTo(account.getUsername());message.setSubject(subject);message.setText("Use this one-time link within "+lifetime.toHours()+" hours: "+frontendUrl+path+raw+"\nIf you did not request this, ignore this message.");mail.send(message);audit.record(account.getUsername(),account.getRole(),account.getBusinessId(),"AUTH_"+type,"USER",account.getId().toString(),"SUCCESS","{}");}
 @Transactional public void verifyEmail(String raw){EmailActionToken token=consume(raw,"VERIFY_EMAIL");UserAccount a=accounts.findById(token.getAccountId()).orElseThrow();a.setEmailVerified(true);}
 @Transactional public void resetPassword(String raw,String password,org.springframework.security.crypto.password.PasswordEncoder encoder,TokenService sessions){EmailActionToken token=consumeOneOf(raw,java.util.Set.of("RESET_PASSWORD","SET_PASSWORD"));UserAccount a=accounts.findById(token.getAccountId()).orElseThrow();a.setPasswordHash(encoder.encode(password));if("SET_PASSWORD".equals(token.getActionType()))a.setEmailVerified(true);sessions.revokeUser(a.getUsername());}
 private EmailActionToken consume(String raw,String action){return consumeOneOf(raw,java.util.Set.of(action));}
 private EmailActionToken consumeOneOf(String raw,java.util.Set<String> actions){if(raw==null||raw.length()<30||raw.length()>200)throw new IllegalArgumentException("Invalid or expired token.");EmailActionToken t=tokens.findByTokenHashForUpdate(hash(raw)).filter(EmailActionToken::isUsable).orElseThrow(()->new IllegalArgumentException("Invalid or expired token."));if(!actions.contains(t.getActionType()))throw new IllegalArgumentException("Invalid or expired token.");t.consume();return t;}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
